$('#arrow').onclick=()=>{connectionType='arrow';$('#arrow').classList.add('chosen');$('#line').classList.remove('chosen')};$('#line').onclick=()=>{connectionType='line';$('#line').classList.add('chosen');$('#arrow').classList.remove('chosen')};
