const stopWords=new Set('a an the and or to of in on is it i my me we you your for with that this are was be have do but as at so from just can will want need some'.split(' '));function keywords(text){return new Set((text.toLowerCase().match(/[\p{L}\p{N}]{3,}/gu)||[]).filter(w=>!stopWords.has(w)).map(w=>w.replace(/(ing|es|s)$/,'')))}
$('#sort').onclick=()=>{let added=0;for(let i=0;i<state.notes.length;i++)for(let j=i+1;j<state.notes.length;j++){const a=state.notes[i],b=state.notes[j],ka=keywords(a.text),kb=keywords(b.text);if([...ka].some(w=>kb.has(w))){const count=state.edges.length;connect(a.id,b.id);added+=state.edges.length-count}}toast(added?`Connected ${added} related ${added===1?'pair':'pairs'} using shared words.`:'No new matches. Notes with shared words can be connected.');};
