$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();document.addEventListener('keydown',e=>{if(e.target.closest('input,select,[contenteditable=true]')||$('#help-dialog').open)return;if(e.key.toLowerCase()==='n'){e.preventDefault();addNote()}if(e.key.toLowerCase()==='v')setTool('select');if(e.key==='Escape'){selected=null;setTool('select');render()}});
